/**
 * @brief Updates UI elements related to the loaded (or active) trajectory.
 */
void MainWindow::UpdateTrajectoryControls() {
    const auto n_poses = QString::number(trajectory_.size());
    if (trajectory_.empty()) {
        // Nothing recorded or loaded
        ui_->l_trajectory_name->setText("...");
        ui_->l_trajectory_step->setText("...");
    } else if (trajectory_file_.isEmpty()) {
        // Unsaved recording
        ui_->l_trajectory_name->setText("Recording");
        ui_->l_trajectory_step->setText(n_poses + "/-");  // total unknown
    } else {
        // From file
        ui_->l_trajectory_name->setText(
            QFileInfo(trajectory_file_).completeBaseName());
        ui_->l_trajectory_step->setText(
            "-/" + n_poses);  // step unknown (not started yet)
    }
    if (trajectory_step_) {
        // Regardless of state
        ui_->l_trajectory_step->setText(GetTrajectoryStepText());
    }

    // Clearly display which state is active
    if (trajectory_playing_) {
        ui_->pb_trajectory_play->setIcon(
            QIcon::fromTheme(QIcon::ThemeIcon::MediaPlaybackPause));
        ui_->pb_trajectory_play->setText(" PAUSE");
        ui_->pb_trajectory_play->setStyleSheet(
            QString("QPushButton:enabled {color: %1;}").arg(Color::kRed));
    } else {
        ui_->pb_trajectory_play->setIcon(
            QIcon::fromTheme(QIcon::ThemeIcon::MediaPlaybackStart));
        ui_->pb_trajectory_play->setText(" PLAY");
        ui_->pb_trajectory_play->setStyleSheet(
            QString("QPushButton:enabled {color: %1;}").arg(Color::kGreen));
    }

    ui_->pb_trajectory_clear->setEnabled(!trajectory_.empty()
                                         && !trajectory_playing_);
    ui_->a_trajectory_load->setEnabled(!trajectory_playing_);
    ui_->a_trajectory_save->setEnabled(!trajectory_.empty());

    UpdateActuatorControls();
}

/**
 * @brief Starts or stops trajectory playback, locking controls that would
 *        interfere while it plays.
 *
 * @param playing Whether the trajectory is playing
 */
void MainWindow::SetTrajectoryPlaying(const bool& playing) {
    trajectory_playing_ = playing;
    if (!playing) {
        hold_timer_->stop();
    }

    // UI widgets
    UpdateTrajectoryControls();
    UpdateModeControls();
}

/**
 * @brief Starts the current trajectory step: applies its counterweight (CW)
 *        action, if any, then sends its pose. If CW isn't connected: pauses
 *        playback.
 *
 * @note CW actions use the same controls as the user (motion mode, fill and
 *       drain buttons), so their checks and guards still apply.
 *
 * @note "Trajectory step i/n started" and "... reached" (see
 *       `HandleMovementStateChanged()`) mark each step in the log and, with
 *       ROS2, in `/rosout` for analysis; KEEP THEIR WORDING STABLE!!
 */
void MainWindow::SendTrajectoryStep() {
    const auto& step = trajectory_[*trajectory_step_];

    if (step.mode || step.cw) {
        if (!ui_->a_water_cw_disconnect->isEnabled()) {
            HandleCriticalError("Trajectory - Step " + GetTrajectoryStepText()
                                + " needs the CW connected");
            SetTrajectoryPlaying(false);
            return;
        }

        if (step.mode) {
            SetMotionMode(*step.mode);
        }

        // Click each side's buttons into the requested state (side B is null
        // when the robot doesn't have it)
        for (auto [fill, drain] : {
                 std::pair{ui_->pb_water_fill_A, ui_->pb_water_drain_A},
                 std::pair{ui_->pb_water_fill_B, ui_->pb_water_drain_B}
        }) {
            if (!step.cw || fill == nullptr || drain == nullptr) {
                continue;
            }
            if (fill->isChecked() != (*step.cw == Motion::CwCommand::kFill)) {
                fill->click();
            }
            if (drain->isChecked() != (*step.cw == Motion::CwCommand::kDrain)) {
                drain->click();
            }
        }
    }

    logger_->Info("Trajectory step " + GetTrajectoryStepText().toStdString()
                  + " started" + GetTrajectoryLoopText().toStdString());
    SendJointTargets(step.pose);
}

/**
 * @brief Moves to the next trajectory step once arm has settled; wraps around
 *        if looping, otherwise finishes playback.
 *
 * @note Only used by `hold_timer_` (see signal/slot connection in
 *       `ConfigureUi()`); separate function for readability.
 */
void MainWindow::PlayNextTrajectoryStep() {
    // Calculate next step
    const bool reverse = ui_->pb_trajectory_reverse->isChecked();
    const std::size_t first = reverse ? trajectory_.size() - 1 : 0;
    const std::size_t last = reverse ? 0 : trajectory_.size() - 1;

    if (*trajectory_step_ == last && !ui_->chk_trajectory_loop->isChecked()) {
        logger_->Info("Trajectory complete");
        trajectory_step_.reset();
        SetTrajectoryPlaying(false);
        EndTrajectoryRun("complete");
        return;
    }

    if (*trajectory_step_ == last) {
        trajectory_step_ = first;  // loop
        ++trajectory_loop_;
        AppendRunMetadata("loop " + QString::number(trajectory_loop_)
                          + " started");
    } else {
        trajectory_step_ = reverse ? *trajectory_step_ - 1
                                   : *trajectory_step_ + 1;
    }

    // Ask for confirmation (if necessary) before proceeding
    if (ui_->chk_trajectory_confirm->isChecked() && !ConfirmTrajectoryStep()) {
        logger_->Info("Trajectory paused before step "
                      + GetTrajectoryStepText().toStdString());
        SetTrajectoryPlaying(false);
        return;
    }

    // Send next step to actuators and update UI
    SendTrajectoryStep();

    UpdateTrajectoryControls();
}

/**
 * @brief Asks the user for confirmation before proceeding to the next
 *        trajectory step.
 *
 * @note "OK (don't ask again)" unchecks "Confirm steps".
 */
bool MainWindow::ConfirmTrajectoryStep() {
    const auto& step = trajectory_[*trajectory_step_];

    QString text = "Move to step " + GetTrajectoryStepText() + "?\n";
    for (std::size_t i = 0; i < Motion::kNumJoints; ++i) {
        const auto joint = static_cast<Joint::Name>(i);
        text += "\n" + QString::fromStdString(Joint::NameEnumToString(joint))
                + ": " + QString::number(step.pose[i]) + " deg";
    }
    if (step.hold_s) {
        text += "\nHold: " + QString::number(*step.hold_s) + " s";
    }
    if (step.mode) {
        text += "\nMotion mode: "
                + QString::fromStdString(
                    Motion::MotionModeEnumToString(*step.mode));
    }
    if (step.cw) {
        text += "\nCW: "
                + QString::fromStdString(
                    Motion::CwCommandEnumToString(*step.cw));
    }

    QMessageBox box(QMessageBox::Question, "Trajectory", text,
                    QMessageBox::Cancel, this);
    const auto* ok = box.addButton("OK", QMessageBox::AcceptRole);
    const auto* ok_always = box.addButton("OK (don't ask again)",
                                          QMessageBox::AcceptRole);
    box.setDefaultButton(QMessageBox::Cancel);
    box.exec();

    if (box.clickedButton() == ok_always) {
        ui_->chk_trajectory_confirm->setChecked(false);
        return true;
    }

    return box.clickedButton() == ok;
}

/**
 * @brief Gets the current trajectory step as "step/total" (1-based).
 */
QString MainWindow::GetTrajectoryStepText() const {
    return QString::number(*trajectory_step_ + 1) + "/"
           + QString::number(trajectory_.size());
}

/**
 * @brief Gets the current loop as " (loop n)" for log messages; empty on the
 *        first time through the trajectory.
 */
QString MainWindow::GetTrajectoryLoopText() const {
    return trajectory_loop_ > 1
               ? " (loop " + QString::number(trajectory_loop_) + ")"
               : QString();
}

/**
 * @brief Starts a run. Allows the user to specify a note, writes the
 *        run's metadata file, and starts a hebilog (if none is active).
 *
 * @note The metadata file is `./log/run_<date>_<time>.txt`. Events during the
 *       run (hebilog, loops, aborts, end) are appended to it with their time.
 *
 * @see EndTrajectoryRun AppendRunMetadata
 */
bool MainWindow::StartTrajectoryRun() {
    // Query user for custom note
    bool ok = false;
    const QString note = QInputDialog::getText(this, "Trajectory Run",
                                               "Run note (optional):",
                                               QLineEdit::Normal, {}, &ok);
    if (!ok) {
        return false;
    }

    // Create and open metadata file
    const QDir log_dir("./log");
    if (!log_dir.exists() && !log_dir.mkpath(".")) {
        HandleCriticalError("Trajectory - Failed to create log directory");
        return false;
    }
    const auto now = QDateTime::currentDateTime();
    QFile file(log_dir.filePath("run_" + now.toString("yyyy-MM-dd_HH-mm-ss")
                                + ".txt"));
    if (!file.open(QIODevice::WriteOnly | QIODevice::Text)) {
        HandleCriticalError("Trajectory - Failed to write run metadata to "
                            + file.fileName());
        return false;
    }

    // Get and write metadata (commit, torque bounds, etc.)
    QProcess git;
    git.start("git",
              {"-C", LIBRA_SOURCE_DIR, "describe", "--always", "--dirty"});
    const QString commit = git.waitForFinished(2000) && git.exitCode() == 0
                               ? QString(git.readAllStandardOutput()).trimmed()
                               : "unknown";

    const auto [cw_lower_bound,
                cw_upper_bound] = hebi_thread_->GetReactiveCwBounds();
    const std::array tanks{ui_->tw_water_level_A, ui_->tw_water_level_B};
    QStringList volumes;
    for (std::size_t i = 0; i < Water::kSideCount; ++i) {
        volumes << QString::fromStdString(
                       Water::SideEnumToString(static_cast<Water::Side>(i)))
                       + " "
                       + QString::number(tanks.at(i)->GetVolume(), 'f', 2);
    }

    QTextStream out(&file);
    out << "# LIBRA trajectory run metadata\n"
        << "started: " << now.toString("yyyy-MM-dd HH:mm:ss") << "\n"
        << "libra_version: " << LIBRA_VERSION << "\n"
        << "build_with_ros2: " << (kBuildWithRos2 ? "true" : "false") << "\n"
        << "commit: " << commit << "\n"
        << "trajectory: "
        << (trajectory_file_.isEmpty() ? "unsaved recording" : trajectory_file_)
        << " (" << trajectory_.size() << " steps)\n"
        << "direction: "
        << (ui_->pb_trajectory_reverse->isChecked() ? "reverse" : "forward")
        << "\n"
        << "loop: " << (ui_->chk_trajectory_loop->isChecked() ? "on" : "off")
        << "\n"
        << "hold_s: " << t_hold_s_ << "\n"
        << "motion_mode: "
        << QString::fromStdString(Motion::MotionModeEnumToString(motion_mode_))
        << "\n"
        << "reactive_cw_bounds_nm: " << cw_lower_bound << ", " << cw_upper_bound
        << "\n"
        << "cw_volume_l: " << volumes.join(", ") << "\n"
        << "gains: " << gains_file_ << "\n"
        << "safety: " << safety_file_ << "\n"
        << "note: " << note << "\n";

    run_file_ = file.fileName();
    trajectory_loop_ = 1;
    logger_->Info("Started trajectory run (metadata: " + run_file_.toStdString()
                  + ")");

    if (hebilog_file_.isEmpty()) {
        run_started_hebilog_ = true;
        ui_->a_hebi_log_start->trigger();
    }

    return true;
}

/**
 * @brief Ends the active run, if any.
 *
 * @note Stops the active hebilog if the run started it.
 *
 * @param outcome Why the run ended (e.g., "complete")
 */
void MainWindow::EndTrajectoryRun(const QString& outcome) {
    if (run_file_.isEmpty()) {
        return;
    }

    AppendRunMetadata("ended (" + outcome + ")");
    logger_->Info("Ended trajectory run (" + outcome.toStdString() + ")");
    run_file_.clear();

    if (run_started_hebilog_ && !hebilog_file_.isEmpty()) {
        ui_->a_hebi_log_stop->trigger();
    }
    run_started_hebilog_ = false;
}

/**
 * @brief Appends a timestamped event to the active run's metadata file, if
 *        any.
 *
 * @param text Event description
 */
void MainWindow::AppendRunMetadata(const QString& text) {
    if (run_file_.isEmpty()) {
        return;
    }

    QFile file(run_file_);
    if (!file.open(QIODevice::Append | QIODevice::Text)) {
        logger_->Error("Failed to append to run metadata: "
                       + run_file_.toStdString());
        return;
    }
    QTextStream(&file) << QTime::currentTime().toString("HH:mm:ss") << " "
                       << text << "\n";
}

